SELECT     TRUNC(SYSDATE)                                        AS report_date,     md.HALF_NO                                            AS fiscal_half,     md.MONTH_NO                                           AS fiscal_month,     p.CURR_454_MONTH                                      AS curr_454_month,     p.CURR_454_YEAR                                       AS curr_454_year,     p.START_454_MONTH                                     AS month_start_date,     p.END_454_MONTH                                       AS month_end_date,     md.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     d.PROFIT_CALC_TYPE                                    AS accounting_method,     CASE d.PROFIT_CALC_TYPE         WHEN 1 THEN 'Cost Method'         WHEN 2 THEN 'Retail Method'     END                                                   AS accounting_method_desc,     md.LOCATION                                           AS location_id,     md.LOC_TYPE                                           AS loc_type,     CASE md.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE md.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,        md.CURRENCY_IND                                       AS currency_ind,     md.SHRINKAGE_RETAIL                                   AS actual_shrink_retail,     md.SHRINKAGE_COST                                     AS actual_shrink_cost,     CASE         WHEN NVL(md.NET_SALES_RETAIL, 0) > 0         THEN ROUND(NVL(md.SHRINKAGE_RETAIL, 0)                    / md.NET_SALES_RETAIL * 100, 4)     END                                                   AS actual_shrink_pct_sales,     CASE         WHEN NVL(md.HTD_GAFS_RETAIL, 0) > 0         THEN ROUND(NVL(md.SHRINKAGE_RETAIL, 0)                    / md.HTD_GAFS_RETAIL * 100, 4)     END                                                   AS actual_shrink_pct_gafs,     ROUND(NVL(md.HTD_GAFS_RETAIL, 0)           * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2)          AS implied_half_budget_shrink,     hdb.SHRINKAGE_PCT                                     AS half_budget_shrinkage_pct,     hdb.MARKDOWN_PCT                                      AS half_budget_markdown_pct,     hdb.GROSS_MARGIN_PCT                                  AS half_budget_gm_pct,     ROUND(NVL(md.SHRINKAGE_RETAIL, 0)           - ROUND(NVL(md.HTD_GAFS_RETAIL, 0)                   * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2), 2)                                                           AS shrink_variance_retail,     ROUND(NVL(md.SHRINKAGE_COST, 0)           - ROUND(NVL(md.HTD_GAFS_COST, 0)                   * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2), 2)                                                           AS shrink_variance_cost,     ROUND(         (NVL(md.SHRINKAGE_RETAIL, 0)          - ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2))         / NULLIF(ROUND(NVL(md.HTD_GAFS_RETAIL, 0)                        * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2), 0)         * 100, 2)                                         AS variance_pct_of_budget,     CASE         WHEN NVL(hdb.SHRINKAGE_PCT, 0) = 0              AND NVL(md.SHRINKAGE_RETAIL, 0) > 0         THEN 'OVER BUDGET - No Allowance Set'         WHEN NVL(md.SHRINKAGE_RETAIL, 0) > ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2)              AND (NVL(md.SHRINKAGE_RETAIL, 0)                   - ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2))                  / NULLIF(ROUND(NVL(md.HTD_GAFS_RETAIL, 0)                                 * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 0.001), 0) > 0.20         THEN 'OVER BUDGET >20% - Investigate'         WHEN NVL(md.SHRINKAGE_RETAIL, 0) > ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2)         THEN 'OVER BUDGET'         WHEN NVL(md.SHRINKAGE_RETAIL, 0)              = ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2)         THEN 'AT BUDGET'         WHEN NVL(md.SHRINKAGE_RETAIL, 0) < ROUND(NVL(md.HTD_GAFS_RETAIL, 0) * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2)         THEN 'UNDER BUDGET (Favourable)'         ELSE 'NO ACTUAL SHRINK RECORDED'     END                                                   AS budget_status,     ROUND(         CASE             WHEN NVL(md.NET_SALES_RETAIL, 0) > 0             THEN NVL(md.SHRINKAGE_RETAIL, 0) / md.NET_SALES_RETAIL * 100         END         - NVL(hdb.SHRINKAGE_PCT, 0), 2)                  AS shrink_rate_vs_cmo_budget,       CASE         WHEN NVL(md.NET_SALES_RETAIL, 0) > 0              AND (NVL(md.SHRINKAGE_RETAIL, 0) / md.NET_SALES_RETAIL * 100) > NVL(hdb.SHRINKAGE_PCT, 0)         THEN 'ACTUAL RATE EXCEEDS CMO ALLOWANCE'         WHEN NVL(md.NET_SALES_RETAIL, 0) > 0              AND (NVL(md.SHRINKAGE_RETAIL, 0) / md.NET_SALES_RETAIL * 100) <= NVL(hdb.SHRINKAGE_PCT, 0)         THEN 'WITHIN CMO ALLOWANCE'         ELSE 'INSUFFICIENT SALES DATA'     END                                                   AS cmo_compliance_status,     md.NET_SALES_RETAIL                                   AS net_sales_retail,     md.NET_SALES_COST                                     AS net_sales_cost,     md.HTD_GAFS_RETAIL                                    AS htd_gafs_retail,     md.HTD_GAFS_COST                                      AS htd_gafs_cost,     md.OPN_STK_RETAIL                                     AS open_stock_retail,     md.OPN_STK_COST                                       AS open_stock_cost,     md.CLS_STK_RETAIL                                     AS close_stock_retail,     md.CLS_STK_COST                                       AS close_stock_cost,       -- ── Stocktake Context ─────────────────────────────────────     md.STOCKTAKE_MTD_SHRINK_AMT                           AS stocktake_mtd_shrink,     md.STOCKTAKE_MTD_SALES_AMT                            AS stocktake_mtd_sales,     md.STOCKTAKE_BOOKSTK_RETAIL                           AS stocktake_book_stock,     md.STOCKTAKE_ACTSTK_RETAIL                            AS stocktake_actual_stock,     hd.INTER_STOCKTAKE_SHRINK_AMT                         AS inter_stock_take_shrink,     hd.INTER_STOCKTAKE_SALES_AMT                          AS inter_stock_take_sales,     hd.SHRINKAGE_PCT                                      AS half_actual_shrinkage_pct,     (SELECT STD_AV_IND FROM RDS_WV_SYSTEM_OPTIONS      WHERE ROWNUM = 1)                                    AS cost_method,     CASE (SELECT STD_AV_IND FROM RDS_WV_SYSTEM_OPTIONS           WHERE ROWNUM = 1)         WHEN 'A' THEN 'Average Cost'         WHEN 'S' THEN 'Standard Cost'     END                                                   AS cost_method_desc   FROM     (         SELECT             md2.HALF_NO,             md2.MONTH_NO,             md2.DEPT,             md2.LOCATION,             md2.LOC_TYPE,             md2.CURRENCY_IND,             md2.EOM_DATE,             SUM(md2.SHRINKAGE_RETAIL)   AS SHRINKAGE_RETAIL,             SUM(md2.SHRINKAGE_COST)     AS SHRINKAGE_COST,             SUM(md2.NET_SALES_RETAIL)   AS NET_SALES_RETAIL,             SUM(md2.NET_SALES_COST)     AS NET_SALES_COST,             SUM(md2.HTD_GAFS_RETAIL)    AS HTD_GAFS_RETAIL,             SUM(md2.HTD_GAFS_COST)      AS HTD_GAFS_COST,             SUM(md2.OPN_STK_RETAIL)     AS OPN_STK_RETAIL,             SUM(md2.OPN_STK_COST)       AS OPN_STK_COST,             SUM(md2.CLS_STK_RETAIL)     AS CLS_STK_RETAIL,             SUM(md2.CLS_STK_COST)       AS CLS_STK_COST,             SUM(md2.STOCKTAKE_MTD_SHRINK_AMT)  AS STOCKTAKE_MTD_SHRINK_AMT,             SUM(md2.STOCKTAKE_MTD_SALES_AMT)   AS STOCKTAKE_MTD_SALES_AMT,             SUM(md2.STOCKTAKE_BOOKSTK_RETAIL)  AS STOCKTAKE_BOOKSTK_RETAIL,             SUM(md2.STOCKTAKE_ACTSTK_RETAIL)   AS STOCKTAKE_ACTSTK_RETAIL         FROM  RDS_WV_MONTH_DATA   md2         WHERE md2.EOM_DATE >= ADD_MONTHS(SYSDATE, -6)         GROUP BY             md2.HALF_NO, md2.MONTH_NO,             md2.DEPT, md2.LOCATION,             md2.LOC_TYPE, md2.CURRENCY_IND,             md2.EOM_DATE     )                                                     md     LEFT JOIN RDS_WV_PERIOD       p    ON  TRUNC(md.EOM_DATE) = TRUNC(p.VDATE)     JOIN  RDS_WV_DEPS             d    ON  md.DEPT      = d.DEPT     LEFT JOIN RDS_WV_HALF_DATA_BUDGET hdb                                                 ON  md.DEPT      = hdb.DEPT                                                AND  md.LOCATION  = hdb.LOCATION                                                AND  md.HALF_NO   = hdb.HALF_NO     LEFT JOIN RDS_WV_HALF_DATA    hd   ON  md.DEPT      = hd.DEPT                                                AND  md.LOCATION  = hd.LOCATION                                                AND  md.HALF_NO   = hd.HALF_NO     LEFT JOIN RDS_WV_STORE        st   ON  md.LOCATION  = st.STORE                                                AND  md.LOC_TYPE  = 'S'     LEFT JOIN RDS_WV_WH           wh   ON  md.LOCATION  = wh.WH                                                AND  md.LOC_TYPE  = 'W'  ORDER BY     md.HALF_NO,     md.MONTH_NO,     ROUND(NVL(md.SHRINKAGE_RETAIL, 0)           - ROUND(NVL(md.HTD_GAFS_RETAIL, 0)                   * NVL(hdb.SHRINKAGE_PCT, 0) / 100, 2), 2) DESC,     d.DEPT_NAME,     CASE md.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END